import{_ as a,o as s,c as i,a6 as o}from"./chunks/framework.CKIbuWFA.js";const h=JSON.parse('{"title":"Normalización de eventos, lotes y huecos","description":"","frontmatter":{"title":"Normalización de eventos, lotes y huecos","docId":"developer.events","translationKey":"developer.events","locale":"es","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"caded5529a62e826a91d2deb86936c29c709ac713c2a0cd021f467b1dfa2b6e7","translationRevision":"381296887776b3746ddfc5e6a2d66dc6ec0c9bcd48fead1acda9343e491b86d1","order":100},"headers":[],"relativePath":"es/developer/events.md","filePath":"es/developer/events.md","lastUpdated":1794611623000}'),t={name:"es/developer/events.md"};function n(r,e,l,d,c,p){return s(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="event-normalization-batches-and-gaps" tabindex="-1">Normalización de eventos, lotes y huecos <a class="header-anchor" href="#event-normalization-batches-and-gaps" aria-label="Permalink to &quot;Normalización de eventos, lotes y huecos {#event-normalization-batches-and-gaps}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo y requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo y requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Consume eventos LIVE sin contabilizarlos dos veces ni confundir recuperación visual con ejecución. Conoce la <a href="./storage.html">persistencia</a> y utiliza muestras saneadas en lugar de capturas de cuentas reales. <code>tiktools-tiktok</code> envuelve las dependencias fijadas de firma y decodificación y exporta valores estables; el núcleo no publica objetos protobuf como API de aplicación.</p><h2 id="follow-the-implemented-pipeline" tabindex="-1">Seguir el recorrido implementado <a class="header-anchor" href="#follow-the-implemented-pipeline" aria-label="Permalink to &quot;Seguir el recorrido implementado {#follow-the-implemented-pipeline}&quot;">​</a></h2><p>La entrada captura el contexto original de creador/sala antes del trabajo asíncrono. La normalización produce chat, regalos, likes, eventos sociales y de ciclo de vida. El núcleo publica originales y gestiona por separado contabilidad y efectos. Los procesadores pueden adjuntar evidencia acotada en <code>event.intel</code>; ante fallos conservan el evento y registran degradación. Los contratos generados describen únicamente campos emitidos.</p><p>La identidad de repetición incluye creador, sala, método, tipo e identificador de mensaje distinto de cero. Sin identificador no se demuestra repetición. Los combos usan identidad de remitente/regalo/grupo y máximos acumulados, por lo que el paquete final no vuelve a premiar la cantidad. Los precios desconocidos permanecen en cero. Las transiciones agregadas permiten detectar <code>previous &lt; threshold &lt;= total</code> sin reemplazar los originales públicos.</p><h2 id="implement-a-consumer" tabindex="-1">Implementar un consumidor <a class="header-anchor" href="#implement-a-consumer" aria-label="Permalink to &quot;Implementar un consumidor {#implement-a-consumer}&quot;">​</a></h2><ol><li>Usa los tipos de <code>src/automation/contracts/generated/</code> o el analizador de sobres del widget, según el límite.</li><li>Conserva cursores al serializar y elimina solapamientos entre tiempo real y recuperación.</li><li>Procesa lotes ordenados sin renderizar reactivamente una vez por evento.</li><li>Muestra señales de hueco y sobrecarga. Recupera la presentación con páginas acotadas o una instantánea, nunca ejecutando puntos o acciones otra vez.</li></ol><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> contracts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> live-feed-state</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> automation</span></span></code></pre></div><p>Los <a href="https://github.com/nglmercer/TikTools-app/tree/remake/crates/tiktools-core/src/contracts" target="_blank" rel="noreferrer">contratos Rust</a> generan registro, esquemas y muestras; evita copiar manualmente tablas completas de campos.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado y estado <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Resultado esperado y estado {#expected-result-and-status}&quot;">​</a></h2><p>El solapamiento de reconexión solo se deduplica mientras el evento identificado permanezca en el almacén finito actual. Colas, contadores, historial y cachés permanecen acotados. No es un archivo ilimitado ni una garantía universal de ejecución única. Agotar capacidad o perder persistencia afecta explícitamente a la salud.</p><h2 id="recover-and-verify" tabindex="-1">Recuperación y verificación <a class="header-anchor" href="#recover-and-verify" aria-label="Permalink to &quot;Recuperación y verificación {#recover-and-verify}&quot;">​</a></h2><p>Utiliza muestras saneadas de regalos/emotes y prueba finales de combo, identificadores ausentes, cambios de sala y huecos. Consulta la revisión del firmador en <code>Cargo.toml</code>, no un hash antiguo. Los métodos desconocidos siguen sin semántica inventada hasta ampliar normalización y contratos.</p><h2 id="operational-details" tabindex="-1">Detalles de operación <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Detalles de operación {#operational-details}&quot;">​</a></h2><p>Los defaults actuales (2026-11-13) son límites de implementación, no un SLA. La entrada LIVE admite 2.048 elementos y el canal de efectos 128; no son presupuestos de bytes. El ciclo de vida espera capacidad. Regalos/follows/shares esperan como máximo un segundo antes de descartarse con hueco. Chat/likes/joins/otros datos se descartan inmediatamente al saturarse. Revisa <code>droppedCritical</code>, lotes/unidades de likes perdidos y pérdidas de efectos: una entrada descartada puede no haber ejecutado sus efectos. Backfill solo repara presentación, nunca puntos ni acciones.</p><p>La deduplicación guarda como máximo 4.096 identidades durante 300 segundos en memoria del proceso. Sobrevive a reconexiones solo mientras vive ese almacén. Caducidad, expulsión, IDs ausentes o reinicio eliminan la protección; el solapamiento solo está protegido dentro de esos límites.</p><p><code>ui.feed.backfill</code> acepta <code>{version:1,after:0,limit:64}</code>, cursor numérico global y límite 1–512. Revisa <code>oldestCursor</code>, <code>latestCursor</code>, <code>gap</code> y <code>truncated</code>; continúa desde el último cursor recibido. <code>ui.feed.creator</code> usa <code>{creatorId,streamId,after,limit}</code>, cursores de texto, stream por creador, límite 1–64 y presupuesto de bytes. No intercambies cursores. Si cambia/se expulsa el stream, el cursor es futuro, hay hueco de ingreso o <code>CreatorFeedUnavailable</code>, refresca la presentación autoritativa y marca la historia faltante; no inventes efectos.</p><p>TikTok inicializa sesión, sala, catálogo de regalos, bundle de firma y socket. Configuración: <code>TIKTOOLS_TIKTOK_SIGNING_BUNDLE</code>, <code>TIKTOOLS_TIKTOK_BUNDLE_CACHE</code>, <code>TIKTOOLS_TIKTOK_BUNDLE_URL</code>. Defaults: cinco intentos, backoff inicial 2 s hasta 30 s. HTTP 429 usa Retry-After o mínimo creciente 30–300 s con jitter, hasta dos reintentos por rate limit; conserva cooldown tras cancelar/agotarse. Otros reintentos exigen fallo transitorio de transporte. Revisa <code>Reconnecting { attempt, delay_ms }</code> y la etapa; no adjuntes cookies ni material privado de firma.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system.health</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{}&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span></code></pre></div>`,20)])])}const m=a(t,[["render",n]]);export{h as __pageData,m as default};
